create table if not exists company_integrations (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, provider text not null check (provider in ('whatsapp','ai')), status text not null default 'disabled', external_account_id text, external_phone_id text, external_business_id text, config jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(company_id,provider));
create table if not exists whatsapp_contacts (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, customer_id uuid references customers(id), wa_id text not null, phone text, name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(company_id,wa_id));
alter table messages add column if not exists external_message_id text;
alter table messages add column if not exists external_status text default 'pending';
alter table messages add column if not exists channel text default 'internal';
create unique index if not exists idx_messages_external_id on messages(company_id,channel,external_message_id) where external_message_id is not null;
create table if not exists ai_settings (id uuid primary key default gen_random_uuid(), company_id uuid not null unique references companies(id) on delete cascade, enabled boolean not null default false, assistant_name text not null default 'Assistente F7', tone text not null default 'professional', business_description text, instructions text, auto_reply boolean not null default false, handoff_enabled boolean not null default true, max_context_messages integer not null default 10, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists usage_counters (company_id uuid not null references companies(id) on delete cascade, metric text not null, period date not null, count integer not null default 0, primary key(company_id,metric,period));
create table if not exists integration_logs (id uuid primary key default gen_random_uuid(), company_id uuid references companies(id) on delete cascade, provider text not null, event text not null, status text not null, external_id text, metadata jsonb not null default '{}', created_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['company_integrations','whatsapp_contacts','ai_settings','usage_counters','integration_logs'] loop execute format('alter table %I enable row level security',t); execute format('drop policy if exists company_isolation on %I',t); execute format('create policy company_isolation on %I for all using (is_company_member(company_id)) with check (is_company_member(company_id))',t); execute format('grant select, insert, update, delete on table %I to authenticated',t); end loop; end $$;
create or replace function company_has_feature(target_company uuid, feature text) returns boolean language plpgsql stable security definer set search_path=public as $$ declare p text; begin select coalesce(plan,'free') into p from company_subscriptions where company_id=target_company; return case feature when 'intelligence' then true when 'automations' then p in ('pro','business','premium') when 'atendimento' then p in ('business','premium') when 'advanced_reports' then p in ('business','premium') when 'whatsapp' then p in ('business','premium') when 'ai' then p='premium' else false end; end; $$;
revoke all on function company_has_feature(uuid,text) from public,anon; grant execute on function company_has_feature(uuid,text) to authenticated;
